Ltac fin9 DG MU WM nd digs :=
  lazymatch goal with FR : rw_cells _ ?mX _ _ |- _ =>
  apply evt_done; exists nd, digs; do 5 eexists;
  split; [unfold ndig, ndigm1; dtests; reflexivity || (cbn; lia) |];
  split; [reflexivity|]; split; [repeat constructor; apply DG; lia|];
  split; [reflexivity|]; split; [exact MU|]; split; [exact WM|]; split; [assumption|];
  apply (cells_reshape _ _ _ _ FR); [ cbn [cells_bytes cbytes Nat.sub]; rewrite ?firstn_firstn; cbn [Nat.min]; rewrite <- ?app_assoc; reflexivity
                                     | cbn; rewrite ?firstn_length_le by lia; repeat split; reflexivity ] end.

Lemma fmt9_walk : forall (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s6 s7 s9 s10 t3 t4 t5 t6 : word)
