Lemma zpadF_walk : forall (i : nat) (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s9 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (pre rest : list byte),
  mem_inv rsegs m -> (1 <= i <= 9)%nat -> length pre = i ->
  rw_cells rsegs m (bv_unsigned s0 + -405) [CB i pre; CB (9 - i) rest] -> (bv_unsigned s0 < 2 ^ 63)%Z -> (1024 <= bv_unsigned s0)%Z ->
  evt rsegs (fun ms' => exists m',
