               (Z_to_bv 64 0xb1550) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned s0 + -405, bv_unsigned s0 + -405 + Z.of_nat i)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ rw_cells rsegs m' (bv_unsigned s0 + -405) [CB 9 (repeat (Z_to_bv 8 48) i ++ rest)])
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 (Z_to_bv 64 (bv_unsigned s0 + -405 + Z.of_nat i)) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7
             (Z_to_bv 64 (bv_unsigned s0 + -405)) s9 (Z_to_bv 64 48) s11 t3 t4 t5 t6) F
        (Z_to_bv 64 0xb1540) fc None m (seg_rom rsegs)).
